package com.gptdrive.app;

import android.content.Context;
import android.content.SharedPreferences;
import org.json.JSONArray;
import org.json.JSONObject;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.SecureRandom;
import java.util.*;
import java.util.concurrent.*;
import javax.net.ssl.*;

/** App-scoped Smart DNS with remote registry, real ChatGPT checks and user filtering. */
final class SmartDnsManager {
    static final String REGISTRY_URL="https://raw.githubusercontent.com/mallstorm/OmniChat-DNS-Registry/main/dns-registry.json";
    private static final String PREFS="gptdrive_smart_dns_v1", ENABLED="enabled", AUTO="auto_select", DISABLED="disabled_routes", MANUAL="manual_route", CACHE="registry_cache", UPDATED="registry_updated";
    private static final String PROBE_HOST="chatgpt.com", PROBE_PATH="/api/auth/session";
    private static final long REFRESH=6*60*60*1000L, DNS_TTL=60_000L, LEASE=5*60*1000L;
    private static final ExecutorService WORK=Executors.newCachedThreadPool(), PROBES=Executors.newFixedThreadPool(3);
    private static final ScheduledExecutorService TIMER=Executors.newSingleThreadScheduledExecutor();
    private static final SecureRandom RAND=new SecureRandom();
    private static final ConcurrentHashMap<String,Stats> STATS=new ConcurrentHashMap<>();
    private static final ConcurrentHashMap<String,DnsCache> DNS_CACHE=new ConcurrentHashMap<>();
    private static volatile Context app; private static volatile boolean initialized; private static volatile List<Resolver> resolvers=Collections.emptyList();
    private static volatile String selectedId="", registryError=""; private static volatile long selectedUntil;

    static final class RouteView {
        final String id,name,mode,endpoint,error; final boolean selected,ok,enabled,blocked; final int statusCode; final long testedAt,dnsMs,tlsMs,httpMs; final double score;
        RouteView(Resolver r,Stats s,boolean sel,boolean en,double sc){id=r.id;name=r.name;mode=r.mode;endpoint=r.endpoint;selected=sel;enabled=en;score=sc;
            ok=s!=null&&s.testedAt>0&&s.ok;blocked=s!=null&&s.blocked;statusCode=s==null?0:s.code;testedAt=s==null?0:s.testedAt;dnsMs=s==null?-1:s.dns;tlsMs=s==null?-1:s.tls;httpMs=s==null?-1:s.http;error=s==null?"":s.error;}
    }
    private static final class Resolver { final String id,name,mode,endpoint; final int priority; final List<String> domains;
        Resolver(String i,String n,String m,String e,int p,List<String>d){id=i;name=n;mode=m;endpoint=e;priority=p;domains=d;}
        boolean matches(String host){if(domains.isEmpty())return true;String h=host.toLowerCase(Locale.ROOT);for(String v:domains){String x=v.toLowerCase(Locale.ROOT).replaceFirst("^\\*?\\.","");if(!x.isEmpty()&&(h.equals(x)||h.endsWith("."+x)))return true;}return false;}}
    private static final class Stats { volatile boolean ok,blocked; volatile int code; volatile long testedAt,dns=-1,tls=-1,http=-1; volatile String error=""; }
    private static final class DnsCache { final long at;final List<InetAddress>a;DnsCache(long t,List<InetAddress>x){at=t;a=x;} }
    private static final class HttpProbe { final int code;final String body;HttpProbe(int c,String b){code=c;body=b==null?"":b;} }
    private SmartDnsManager(){}

    static void initialize(Context c){if(initialized)return;synchronized(SmartDnsManager.class){if(initialized)return;app=c.getApplicationContext();String cached=prefs().getString(CACHE,"");if(!cached.isEmpty())install(cached);initialized=true;
        TIMER.scheduleAtFixedRate(()->{try{if(isEnabled()){refreshIfStale();sweep(false);}}catch(Exception ignored){}},2,15,TimeUnit.MINUTES);}if(isEnabled())WORK.execute(()->{refreshIfStale();sweep(false);});}
    static boolean isEnabled(){return app!=null&&prefs().getBoolean(ENABLED,false);} static boolean isAuto(){return app==null||prefs().getBoolean(AUTO,true);}
    static long lastUpdated(){return app==null?0:prefs().getLong(UPDATED,0);} static String lastRegistryError(){return registryError;}
    static void setEnabled(Context c,boolean on){initialize(c);prefs().edit().putBoolean(ENABLED,on).apply();resetSelection();SmartDnsProxy.applyWebViewRouting(c,null);if(on)refreshAndSweep(c,null);}
    static void setAuto(Context c,boolean on){initialize(c);prefs().edit().putBoolean(AUTO,on).apply();resetSelection();if(!on){Resolver r=best("chatgpt.com");if(r!=null){prefs().edit().putString(MANUAL,r.id).apply();selectedId=r.id;selectedUntil=Long.MAX_VALUE;}}}
    static void setManualRoute(Context c,String id){initialize(c);Resolver r=find(id);if(r==null)return;setRouteEnabled(c,id,true);prefs().edit().putBoolean(AUTO,false).putString(MANUAL,id).apply();selectedId=id;selectedUntil=Long.MAX_VALUE;DNS_CACHE.clear();}
    static void setRouteEnabled(Context c,String id,boolean on){initialize(c);Set<String>s=disabled();if(on)s.remove(id);else s.add(id);prefs().edit().putStringSet(DISABLED,s).apply();if(!on&&id.equals(selectedId))resetSelection();if(!on&&id.equals(prefs().getString(MANUAL,"")))prefs().edit().remove(MANUAL).apply();DNS_CACHE.clear();}
    static void disableFailedRoutes(Context c){initialize(c);Set<String>d=disabled();for(Resolver r:resolvers){Stats s=STATS.get(r.id);if(s!=null&&s.testedAt>0&&!s.ok)d.add(r.id);}prefs().edit().putStringSet(DISABLED,d).apply();if(d.contains(selectedId))resetSelection();}
    static void refreshAndSweep(Context c,Runnable done){initialize(c);WORK.execute(()->{try{refreshRemote();sweep(true);}finally{if(done!=null)done.run();}});}
    static void sweepNow(Context c,Runnable done){initialize(c);WORK.execute(()->{try{sweep(true);}finally{if(done!=null)done.run();}});}
    static void refreshIfStale(){if(app==null)return;if(System.currentTimeMillis()-lastUpdated()>REFRESH||resolvers.isEmpty())refreshRemote();}

    static List<RouteView> routes(){long now=System.currentTimeMillis();Resolver chosen=choose(ranked("chatgpt.com"),now);List<Resolver> all=new ArrayList<>(resolvers);all.sort((a,b)->{boolean ae=routeEnabled(a.id),be=routeEnabled(b.id);if(ae!=be)return ae?-1:1;int c=Double.compare(score(b),score(a));return c!=0?c:Integer.compare(a.priority,b.priority);});List<RouteView> out=new ArrayList<>();for(Resolver r:all)out.add(new RouteView(r,STATS.get(r.id),chosen!=null&&r.id.equals(chosen.id),routeEnabled(r.id),score(r)));return out;}
    static String selectedSummary(){Resolver r=find(selectedId);if(r==null||!routeEnabled(r.id))r=choose(ranked("chatgpt.com"),System.currentTimeMillis());if(r==null)return "System DNS";Stats s=STATS.get(r.id);return(isAuto()?"AUTO · ":"MANUAL · ")+r.name+" · "+r.mode+(s!=null&&s.dns>=0?" · "+s.dns+" ms":"");}

    static Socket connect(Context c,String host,int port)throws Exception{initialize(c);if(!isEnabled())return systemConnect(host,port);refreshIfStale();List<Resolver> list=ranked(host);Resolver first=choose(list,System.currentTimeMillis());List<Resolver> order=new ArrayList<>();if(first!=null)order.add(first);for(Resolver r:list)if(first==null||!r.id.equals(first.id))order.add(r);Exception last=null;
        for(Resolver r:order){long t=System.nanoTime();try{List<InetAddress>a=resolve(r,host);Socket s=connectAddresses(a,port);Stats st=STATS.computeIfAbsent(r.id,k->new Stats());st.dns=ms(t);selectedId=r.id;selectedUntil=isAuto()?System.currentTimeMillis()+LEASE:Long.MAX_VALUE;return s;}catch(Exception e){last=e;}}
        try{return systemConnect(host,port);}catch(Exception e){if(last!=null)throw last;throw e;}}

    private static void refreshRemote(){HttpURLConnection h=null;try{h=(HttpURLConnection)new URL(REGISTRY_URL).openConnection(Proxy.NO_PROXY);h.setConnectTimeout(8000);h.setReadTimeout(10000);h.setRequestProperty("Accept","application/json");h.setRequestProperty("User-Agent","GPTDrive-DNS-Registry/2");if(h.getResponseCode()!=200)throw new IOException("Registry HTTP "+h.getResponseCode());String text=new String(readLimited(h.getInputStream(),512*1024),StandardCharsets.UTF_8);List<Resolver> p=parse(text);if(p.isEmpty())throw new IOException("В реестре нет OpenAI DNS");resolvers=p;prefs().edit().putString(CACHE,text).putLong(UPDATED,System.currentTimeMillis()).apply();registryError="";DNS_CACHE.clear();}catch(Exception e){registryError=e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();}finally{if(h!=null)h.disconnect();}}
    private static void install(String text){try{List<Resolver>p=parse(text);if(!p.isEmpty())resolvers=p;}catch(Exception ignored){}}
    private static List<Resolver> parse(String text)throws Exception{JSONObject root=new JSONObject(text);if(root.optInt("version",1)!=1)throw new IllegalArgumentException("DNS Registry version");JSONArray ps=root.optJSONArray("providers");List<Resolver> out=new ArrayList<>();if(ps==null)return out;
        for(int i=0;i<ps.length();i++){JSONObject p=ps.optJSONObject(i);if(p==null||!p.optBoolean("enabled",true))continue;JSONArray caps=p.optJSONArray("capabilities");boolean openai=caps==null||caps.length()==0;if(caps!=null)for(int j=0;j<caps.length();j++)if("openai".equalsIgnoreCase(caps.optString(j)))openai=true;if(!openai)continue;String base=p.optString("id","provider-"+i),name=p.optString("name",base);int pri=p.optInt("priority",100);List<String>d=new ArrayList<>();JSONArray da=p.optJSONArray("domains");if(da!=null)for(int j=0;j<da.length();j++){String x=da.optString(j).trim();if(!x.isEmpty())d.add(x);}JSONObject proto=p.optJSONObject("protocols");if(proto==null)continue;String doh=proto.optString("doh","").trim(),dot=proto.optString("dot","").trim();if(doh.startsWith("https://"))out.add(new Resolver("remote:"+base+":doh",name,"DoH",doh,pri,d));if(dot.startsWith("tls://"))out.add(new Resolver("remote:"+base+":dot",name,"DoT",dot,pri+1,d));}out.sort(Comparator.comparingInt(r->r.priority));return out;}

    private static void sweep(boolean force){if((!isEnabled()&&!force)||resolvers.isEmpty())return;List<Future<?>>fs=new ArrayList<>();for(Resolver r:resolvers)if(r.matches(PROBE_HOST)&&(force||routeEnabled(r.id)))fs.add(PROBES.submit(()->probe(r)));for(Future<?>f:fs)try{f.get(14,TimeUnit.SECONDS);}catch(Exception ignored){}resetSelection();choose(ranked(PROBE_HOST),System.currentTimeMillis());}
    private static void probe(Resolver r){Stats st=STATS.computeIfAbsent(r.id,k->new Stats());long d0=System.nanoTime();long dns=-1,tls=-1,http=-1;int code=0;SSLSocket ssl=null;try{List<InetAddress>a=resolve(r,PROBE_HOST);dns=ms(d0);long t0=System.nanoTime();Socket raw=connectAddresses(a,443);ssl=(SSLSocket)((SSLSocketFactory)SSLSocketFactory.getDefault()).createSocket(raw,PROBE_HOST,443,true);SSLParameters p=ssl.getSSLParameters();p.setEndpointIdentificationAlgorithm("HTTPS");p.setServerNames(Collections.singletonList(new SNIHostName(PROBE_HOST)));ssl.setSSLParameters(p);ssl.setSoTimeout(6500);ssl.startHandshake();tls=ms(t0);long h0=System.nanoTime();String req="GET "+PROBE_PATH+" HTTP/1.1\r\nHost: "+PROBE_HOST+"\r\nConnection: close\r\nAccept: application/json,text/plain,*/*\r\nAccept-Encoding: identity\r\nUser-Agent: Mozilla/5.0 (Linux; Android 13) AppleWebKit/537.36 Chrome/150.0 Mobile Safari/537.36\r\n\r\n";ssl.getOutputStream().write(req.getBytes(StandardCharsets.US_ASCII));ssl.getOutputStream().flush();HttpProbe hp=readHttp(ssl.getInputStream());http=ms(h0);code=hp.code;String b=hp.body.toLowerCase(Locale.ROOT);boolean blocked=code==451||b.contains("unable to load site")||b.contains("if you are using a vpn")||b.contains("unsupported_country")||b.contains("country is not supported")||b.contains("not available in your country")||b.contains("access denied due to region");boolean ok=!blocked&&((code>=200&&code<400)||code==401||code==404||code==429);st.ok=ok;st.blocked=blocked;st.error=blocked?"ChatGPT блокирует маршрут · HTTP "+code:(ok?"":"ChatGPT HTTP "+code);}catch(Exception e){st.ok=false;st.blocked=false;st.error=e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();}finally{st.code=code;st.testedAt=System.currentTimeMillis();st.dns=dns<0?ms(d0):dns;st.tls=tls;st.http=http;if(ssl!=null)try{ssl.close();}catch(Exception ignored){}}}
    private static HttpProbe readHttp(InputStream in)throws Exception{BufferedReader r=new BufferedReader(new InputStreamReader(in,StandardCharsets.ISO_8859_1));String first=r.readLine();if(first==null||!first.startsWith("HTTP/"))throw new IOException("HTTP probe");String[]p=first.split("\\s+");int code=p.length>1?Integer.parseInt(p[1]):0;String line;while((line=r.readLine())!=null&&!line.isEmpty()){}StringBuilder b=new StringBuilder();char[]buf=new char[2048];int n;while(b.length()<49152&&(n=r.read(buf))!=-1)b.append(buf,0,Math.min(n,49152-b.length()));return new HttpProbe(code,b.toString());}

    private static List<Resolver> ranked(String host){List<Resolver>x=new ArrayList<>();for(Resolver r:resolvers)if(r.matches(host)&&routeEnabled(r.id))x.add(r);x.sort((a,b)->{int c=Double.compare(score(b),score(a));return c!=0?c:Integer.compare(a.priority,b.priority);});return x;}
    private static Resolver best(String host){List<Resolver>x=ranked(host);return x.isEmpty()?null:x.get(0);}
    private static Resolver choose(List<Resolver>x,long now){if(x.isEmpty())return null;if(!isAuto()){Resolver m=find(prefs().getString(MANUAL,""));if(m!=null&&x.contains(m)&&score(m)>-999){selectedId=m.id;selectedUntil=Long.MAX_VALUE;return m;}}Resolver b=x.get(0);Resolver cur=find(selectedId);if(isAuto()&&cur!=null&&selectedUntil>now&&x.contains(cur)&&score(cur)>=score(b)-8)return cur;selectedId=b.id;selectedUntil=isAuto()?now+LEASE:Long.MAX_VALUE;return b;}
    private static double score(Resolver r){Stats s=STATS.get(r.id);if(s!=null&&s.blocked)return-1200;if(s!=null&&s.testedAt>0&&!s.ok)return-1000;if(s==null||s.testedAt==0)return 50+(1000-Math.min(1000,r.priority))/500.0;double latency=Math.max(0,s.dns)+Math.max(0,s.tls)+Math.max(0,s.http);return Math.max(1,100-Math.min(85,latency/35.0));}
    private static Resolver find(String id){if(id==null)return null;for(Resolver r:resolvers)if(id.equals(r.id))return r;return null;} private static boolean routeEnabled(String id){return!disabled().contains(id);} private static Set<String> disabled(){Set<String>s=prefs().getStringSet(DISABLED,Collections.emptySet());return s==null?new HashSet<>():new HashSet<>(s);} private static void resetSelection(){selectedId="";selectedUntil=0;DNS_CACHE.clear();}

    private static List<InetAddress> resolve(Resolver r,String host)throws Exception{String k=r.id+"|"+host.toLowerCase(Locale.ROOT);DnsCache c=DNS_CACHE.get(k);long now=System.currentTimeMillis();if(c!=null&&now-c.at<DNS_TTL)return c.a;List<InetAddress>out=new ArrayList<>();if("DoH".equals(r.mode)){out.addAll(doh(r.endpoint,host,1));out.addAll(doh(r.endpoint,host,28));}else{out.addAll(dot(r.endpoint,host,1));out.addAll(dot(r.endpoint,host,28));}LinkedHashMap<String,InetAddress>u=new LinkedHashMap<>();for(InetAddress a:out)u.put(a.getHostAddress(),a);List<InetAddress>a=new ArrayList<>(u.values());if(a.isEmpty())throw new IOException("DNS не вернул адреса");DNS_CACHE.put(k,new DnsCache(now,a));return a;}
    private static List<InetAddress> doh(String endpoint,String host,int type)throws Exception{byte[]q=query(host,type);HttpsURLConnection h=(HttpsURLConnection)new URL(endpoint).openConnection(Proxy.NO_PROXY);h.setRequestMethod("POST");h.setConnectTimeout(5000);h.setReadTimeout(5000);h.setDoOutput(true);h.setFixedLengthStreamingMode(q.length);h.setRequestProperty("Content-Type","application/dns-message");h.setRequestProperty("Accept","application/dns-message");h.setRequestProperty("Accept-Encoding","identity");try(OutputStream o=h.getOutputStream()){o.write(q);}if(h.getResponseCode()!=200)throw new IOException("DoH HTTP "+h.getResponseCode());byte[]b=readLimited(h.getInputStream(),65536);h.disconnect();return parseDns(b,type);}
    private static List<InetAddress> dot(String endpoint,String host,int type)throws Exception{URI u=URI.create(endpoint);String dh=u.getHost();int port=u.getPort()>0?u.getPort():853;Socket raw=new Socket();raw.connect(new InetSocketAddress(dh,port),5000);raw.setSoTimeout(5000);SSLSocket s=(SSLSocket)((SSLSocketFactory)SSLSocketFactory.getDefault()).createSocket(raw,dh,port,true);SSLParameters p=s.getSSLParameters();p.setEndpointIdentificationAlgorithm("HTTPS");p.setServerNames(Collections.singletonList(new SNIHostName(dh)));s.setSSLParameters(p);s.startHandshake();byte[]q=query(host,type);DataOutputStream o=new DataOutputStream(s.getOutputStream());o.writeShort(q.length);o.write(q);o.flush();DataInputStream i=new DataInputStream(new BufferedInputStream(s.getInputStream()));int n=i.readUnsignedShort();if(n<=0||n>65535)throw new IOException("DoT length");byte[]b=new byte[n];i.readFully(b);s.close();return parseDns(b,type);}
    private static byte[] query(String host,int type)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();DataOutputStream d=new DataOutputStream(b);d.writeShort(RAND.nextInt(65536));d.writeShort(0x0100);d.writeShort(1);d.writeShort(0);d.writeShort(0);d.writeShort(0);for(String label:host.split("\\.")){byte[]x=label.getBytes(StandardCharsets.US_ASCII);d.writeByte(x.length);d.write(x);}d.writeByte(0);d.writeShort(type);d.writeShort(1);d.flush();return b.toByteArray();}
    private static List<InetAddress> parseDns(byte[]d,int wanted)throws Exception{List<InetAddress>out=new ArrayList<>();if(d.length<12)return out;int qd=u16(d,4),an=u16(d,6),p=12;for(int x=0;x<qd;x++){p=skipName(d,p)+4;if(p>d.length)return out;}for(int x=0;x<an&&p<d.length;x++){p=skipName(d,p);if(p+10>d.length)break;int type=u16(d,p),cl=u16(d,p+2),len=u16(d,p+8);p+=10;if(p+len>d.length)break;if(cl==1&&type==wanted&&((type==1&&len==4)||(type==28&&len==16))){byte[]ip=Arrays.copyOfRange(d,p,p+len);out.add(InetAddress.getByAddress(ip));}p+=len;}return out;}
    private static int skipName(byte[]d,int p)throws Exception{for(int g=0;g<128&&p<d.length;g++){int n=d[p]&255;if(n==0)return p+1;if((n&0xC0)==0xC0)return p+2;p+=1+n;}throw new IOException("DNS name");} private static int u16(byte[]d,int p){return((d[p]&255)<<8)|(d[p+1]&255);}
    private static Socket connectAddresses(List<InetAddress>a,int port)throws Exception{Exception last=null;for(InetAddress ip:a){Socket s=new Socket();try{s.connect(new InetSocketAddress(ip,port),5000);s.setSoTimeout(45000);return s;}catch(Exception e){last=e;try{s.close();}catch(Exception ignored){}}}throw last==null?new IOException("No addresses"):last;}
    private static Socket systemConnect(String host,int port)throws Exception{return connectAddresses(Arrays.asList(InetAddress.getAllByName(host)),port);} private static long ms(long t){return Math.max(0,(System.nanoTime()-t)/1_000_000L);} private static byte[] readLimited(InputStream in,int max)throws Exception{try(InputStream i=in;ByteArrayOutputStream o=new ByteArrayOutputStream()){byte[]b=new byte[8192];int total=0,n;while((n=i.read(b))!=-1){total+=n;if(total>max)throw new IOException("Response too large");o.write(b,0,n);}return o.toByteArray();}} private static SharedPreferences prefs(){return app.getSharedPreferences(PREFS,Context.MODE_PRIVATE);}
}
